use bbqr::join::Joined;
use bitcoin::psbt::Psbt;

fn main() {
    let parts= vec!["B$".to_owned()];

    // join the parts
    let joined = Joined::try_from_parts(parts).expect("Failed to join parts");
    let bytes = joined.data;

    let psbt = Psbt::deserialize(&bytes).unwrap();
    println!("PSBT: {:?}", psbt.serialize_hex());
}
